# Pre-normalize all patterns at import time
_NORM_PATTERNS = {
    key: (lambda a: (a - a[0]) / a[0])(np.array(pat, dtype=float))
    for key, pat in _PATTERNS.items()
}

# =========================================================
# HELPERS
# =========================================================

def _normalize(series: np.ndarray) -> np.ndarray:
    return (series - series[0]) / series[0]


# =========================================================
# SMOOTH
# =========================================================

def smooth(ticker: str):
    """
    Compare ticker's 1m close prices against known BUY/SELL patterns
    using DTW distance. Returns the best matching distance or None.
    """
    df = get_data(ticker, '1m')

    if df is None:
        return 0

    closes = np.array(df['Close'].round(4).tolist(), dtype=float)
    n      = len(closes)
    live   = _normalize(closes)

    best_distance = None
    distances     = []

    for key, norm_pat in _NORM_PATTERNS.items():

        # Use last n points of the pattern if pattern is longer
        # Skip if pattern is shorter than live data
        if len(norm_pat) < n:
            continue

        pat_slice = norm_pat[:n]
        distance  = round(dtw.distance(live, pat_slice), 4)
        distances.append(distance)

        ts = dt.datetime.now().strftime('%H:%M:%S')

        if distance <= 0.0100:
            #write("1Smooth.txt", f"{ts},{ticker},{distance:.4f},{key}\n")
            return distance                  # early return on first match
        else:
            pass
            #write("2Smooth.txt", f"{ts},{ticker},{distance:.4f},{key}\n")

    return round(float(np.min(distances)), 4) if distances else 0


